from collections import defaultdict, Counter

def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    cells=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg: cells[g[r][c]].append((r,c))
    out=[row[:] for row in g]
    for col,ps in cells.items():
        if len(ps)<2: continue
        ps=sorted(ps)
        for diag in ('main','anti'):
            key=lambda r,c:(r-c if diag=='main' else r+c)
            for d in {key(r,c) for r,c in ps}:
                line=[(r,c) for r,c in ps if key(r,c)==d]
                if len(line)<2: continue
                line.sort()
                (r1,c1),(r2,c2)=line[0],line[1]
                dr,dc=r1-r2,c1-c2  # direction from second to topmost
                if abs(dr)!=1 or abs(dc)!=1: continue
                r,c=r1+dr,c1+dc
                while 0<=r<h and 0<=c<w:
                    if out[r][c]!=bg: break
                    out[r][c]=col
                    r+=dr; c+=dc
    return out

