lib = '''"""Shared helpers for ARC-style grid tasks."""

def extend_diagonals(grid):
    """Complete same-color diagonal runs (len>=2) over background, never down-right."""
    from collections import Counter
    H, W = len(grid), len(grid[0])
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]
    bgset = {bg, 0}
    g = [row[:] for row in grid]
    dirs_all = {'main': (1, 1), 'anti': (1, -1)}
    for dr, dc in dirs_all.values():
        # group cells into contiguous runs of the same color along this diagonal
        for r0 in range(H):
            for c0 in range(W):
                if (r0 - dr, c0 - dc) in {(x, y) for x in range(H) for y in range(W)}:
                    pass
        # simpler: walk each diagonal line
        for s in range(-(W - 1), H):
            line = []
            if dr == 1 and dc == 1:      # main: r - c = s
                cells = [(r, r - s) for r in range(H) if 0 <= r - s < W]
            else:                        # anti: r + c = s
                cells = [(r, s - r) for r in range(H) if 0 <= s - r < W]
            run = []
            for cell in cells + [None]:
                if cell and g[cell[0]][cell[1]] not in bgset and (
                        not run or g[cell[0]][cell[1]] == g[run[-1][0]][run[-1][1]]):
                    run.append(cell)
                    continue
                if len(run) >= 2:
                    color = g[run[0][0]][run[0][1]]
                    # extend up-left (main) / up-right (anti) and down-left, never down-right
                    for start, step in ((run[0], (-dr, -dc)), (run[-1], (dr, dc))):
                        if step == (1, 1):
                            continue
                        r, c = start[0] + step[0], start[1] + step[1]
                        while 0 <= r < H and 0 <= c < W and g[r][c] in bgset:
                            g[r][c] = color
                            r += step[0]; c += step[1]
                run = [cell] if cell else []
    return g
'''
